 if(m.type==='rhyme'){m.sets=shuf(RH.filter(r=>r[2])).slice(0,3).map(r=>{const ans=r[1+(Math.random()*3|0)];return{w:r[0],ans,opts:shuf([ans,...r[4]])}});m.i=0}
