// ---------- AI Kaz chat (offline canned replies) ----------
const REP=[[/song|lyric|write|music/i,['Right now I\'m chasing a chorus. Want to help me find a rhyme? Click the ✍️ task!','Songs start in my notebook, usually with a coffee next to it.']],
 [/suno|record/i,['Recording day! The 🎙️ task lets you tap the beat for the take.']],
 [/itch|game|app/i,['I make games and apps on itch.io under Coffeebreak. Bugs beware 🐞']],
 [/cloth|no inside|sensory|satin|fashion|karen elizabeth/i,['No Inside Out is all soft seams and no scratchy tags. Karen Elizabeth is the satin side. Pick some colours with me!']],
 [/radio/i,['Coffeebreak Radio plays my songs around the clock. Help me line up the queue!']],
 [/order|ship|supplier/i,['Orders go straight to the supplier, who ships them to the customer. Sort them with me in the 📦 task.']],
 [/coffee|tired|break/i,['Coffee break! A flat white fixes most things ☕']],
 [/hi|hello|hey/i,['Hey! Welcome to the studio 💗','Hi lovely! Pull up a chair.']]];
const GEN=['Ooh, good question! Let\'s see what\'s next on the list.','I\'m on it! Click a task if you want to help.','Thanks for hanging out with me today 💖','Every day here is a bit different. That\'s the fun!'];
function ask(q){for(const [r,a] of REP)if(r.test(q))return R(a);return R(GEN)}
